  const TOPE_ENTRADAS = 32
  const TOPE_BYTES = 128 * 1024 * 1024
  let bytesEnCache = 0
  // Guardar {promesa, bytes} en vez de la promesa suelta, para poder restar al desalojar.

  /** Misma imagen = misma clave. Solo para la CLAVE; que ruta se puede leer es cosa de U-04. */
  function claveDe(p: string) {
    const partes: string[] = []
    for (const t of p.replace(/\//g, '\\').split('\\')) {
      if (t === '' || t === '.') continue
      if (t === '..') { partes.pop(); continue }
      partes.push(t)
    }
    return (p.startsWith('\\\\') ? '\\\\' : '') + partes.join('\\').toLowerCase()
  }

  export function olvidarImagenes() { cacheImagenes.clear(); bytesEnCache = 0 }

